css:
#loader-25 {
  display: inline-grid;
  width: 40px;
  aspect-ratio: 1;
}
#loader-25:before,
#loader-25:after {
  content: '';
  grid-area: 1/1;
  border-radius: 50%;
  background: repeating-conic-gradient(#C02942 0 60deg,#0B486B 0 120deg);
}
#loader-25:before {
  transform: rotate(0turn) translate(100%) rotate(0turn);
  animation: l5 4s linear infinite;
}
#loader-25:after {
  padding: 20%;
  mask: conic-gradient(#000 0 0) content-box exclude,conic-gradient(#000 0 0);
  scale: -1 1;
}
@keyframes l5 {
  to{transform: rotate(1turn) translate(100%) rotate(1turn)}
}
